import {
	Component,
	createEffect,
	createMemo,
	Match,
	mergeProps,
	onCleanup,
	onMount,
	Show,
	splitProps,
	Switch,
	untrack,
} from "solid-js";

import { Filigree } from "#core/ui-next/components/filigree.jsx";
import { PanelProps } from "#core/ui-next/components/panel.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { ImageCache } from "#core/ui-next/utilities/image-cache.js";

type FiligreeType = "icon" | "wide";

export interface OrnateFrameProps extends PanelProps {
	topIconClass?: string;
	topIconSrc?: string;
	topIconTint?: string;
	backgroundImageSrc?: string;
	backgroundImageOpacity?: number;
	topIconBackgroundTint?: string;
	filigreeType?: FiligreeType;
	showFiligrees?: boolean;
	hideTopIcon?: boolean;
	useNoMarginFrame?: boolean;
	isFullscreen?: boolean;
}

const OrnateFrameComponent: Component<OrnateFrameProps> = (props) => {
	const _mergedProps = mergeProps({ backgroundImageOpacity: 80, showCornerFiligrees: true }, props);
	const [filigreeProps, mergedProps] = splitProps(_mergedProps, [
		"topIconClass",
		"topIconSrc",
		"topIconBackgroundTint",
		"topIconTint",
	]);

	let backgroundImageElement: HTMLDivElement | undefined;
	const cache = new ImageCache();

	const backgroundImageUrl = createMemo(() => {
		let url = mergedProps.backgroundImageSrc ?? "blp:bg-panel-mughal";
		if (url.startsWith("url(")) {
			url = url.slice(4, -1).replace(/["']/g, "");
		}

		return url;
	});

	onMount(() => {
		if (backgroundImageElement) {
			createEffect(() => {
				const url = backgroundImageUrl();
				untrack(() => {
					// eslint-disable-next-line solid/reactivity
					cache.loadImage(url).then(() => {
						if (backgroundImageElement) {
							backgroundImageElement.style.backgroundImage = `url(${url})`;
							backgroundImageElement.classList.remove("opacity-0");
							backgroundImageElement.classList.add(`opacity-${_mergedProps.backgroundImageOpacity}`);
						}
					});
				});
			});
		}
	});

	onCleanup(() => {
		cache.unloadAllImages();
	});

	const adjustFrame = false;

	const frameinsetClasses = "px-4 py-5";

	return (
		<div
			{...mergedProps}
			data-name="OrnatePanel"
			class={`pointer-events-auto relative ${props.hideTopIcon ? "" : "mt-12"} ${mergedProps.class ?? ""}`}
		>
			<div
				class={`absolute ${props.isFullscreen ? "fullscreen-outside-safezone" : "inset-0"} ${props.useNoMarginFrame ? "" : frameinsetClasses} pointer-events-none`}
			>
				<div
					ref={backgroundImageElement}
					class={`size-full opacity-0 bg-center bg-no-repeat bg-cover`}
					style={{
						transition: "opacity 0.5s ease-in-out",
					}}
				/>
			</div>

			<div
				class={`${props.useNoMarginFrame ? "ornate-panel-frame-no-margin" : "ornate-panel-frame"} ${props.isFullscreen ? "fullscreen-outside-safezone" : "size-full"} opacity-90 absolute`}
			/>
			<div class={`size-full ${props.useNoMarginFrame ? "" : frameinsetClasses} relative`}>
				<Show when={!props.hideTopIcon}>
					<div class="w-full h-16 flex flex-row justify-center -mt-9 relative">
						<Switch fallback={<Filigree.TopIcon {...filigreeProps} />}>
							<Match when={mergedProps.filigreeType === "icon"}>
								<Filigree.TopIcon {...filigreeProps} />
							</Match>
							<Match when={mergedProps.filigreeType === "wide"}>
								<Filigree.Wide />
							</Match>
						</Switch>
					</div>
				</Show>
				<Show when={mergedProps.showFiligrees}>
					<div
						class="size-64 absolute top-8 left-8 bg-contain bg-no-repeat"
						style={{ "background-image": "url(blp:base_frame-filigree)", opacity: "0.2" }}
					/>
					<div
						class="size-64 absolute top-8 right-8 bg-contain bg-no-repeat rotate-90"
						style={{ "background-image": "url(blp:base_frame-filigree)", opacity: "0.2" }}
					/>
				</Show>
				<Show
					when={adjustFrame}
					fallback={mergedProps.children}
				>
					<div class="absolute inset-0 mx-4 my-5">{mergedProps.children}</div>
				</Show>
			</div>
		</div>
	);
};

export const OrnateFrame = ComponentRegistry.register({
	name: "OrnateFrame",
	images: ["blp:base_frame-filigree"],
	createInstance: OrnateFrameComponent,
});
